310	        claim.setStatus(to);
311	        if (to == ClaimStatus.SETTLED || to == ClaimStatus.PENDING) {
312	            // Settled one at a time until a bulk settle marks it with its batch.
313	            claim.setBatch(null);
314	        }
315	        if (to == ClaimStatus.OPEN) {
316	            claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
317	            claim.setOpenedBy(user);
318	        } else if (to == ClaimStatus.SETTLED) {
319	            claim.setSettledDue(due);
320	        } else if (to == ClaimStatus.VOID) {
321	            claim.setVoidReason(reason);
322	        }
323	        Claim saved = claims.saveAndFlush(claim);
324	        log(sheetId, user, person, saved);
325	        String event = switch (to) {
326	            case OPEN -> "CLAIM_OPENED";
327	            case PENDING -> "CLAIM_PENDING";
328	            case SETTLED -> "CLAIM_SETTLED";
329	            case VOID -> "CLAIM_VOIDED";
330	            case DRAFT, DELETED -> throw new IllegalStateException("A claim is deleted or restored on its own");
331	        };
332	        String line = line(event, sheetId, user, person, saved, saved.getNumber());
333	        if (to == ClaimStatus.SETTLED) {
334	            line += " due=" + settledDueText(saved);
335	        } else if (reversing) {
336	            line += " reversed=" + settledDueText(saved);
337	        }
338	        if (to == ClaimStatus.VOID && reason != null) {
339	            line += " reason=" + reason;
340	        }
341	        audit.recordOnCommit(line);
342	        if (to == ClaimStatus.SETTLED) {
343	            notifyWatchers(sheetId, user, person, saved);
344	        }
345	        return saved;
346	    }
