423	    /** Split an amount off an OPEN claim: it keeps the rest of its amount and loses any figure a
424	     *  statement bound it to, and a new OPEN claim of the split-off amount, with the same date and
425	     *  note, the next number, opened by the user and due by its date plus the terms in force on it,
426	     *  is listed under the person naming the claim it was split from (a late entry when its due-by falls
427	     *  in a soft-closed period). A claim that is not OPEN, one
428	     *  deferred, one dated in a closed period, an amount not above 0.00 and below the claim's, or a
429	     *  user whose role may not open a claim, is refused. */
430	    @Transactional
431	    public Split split(String sheetId, String user, Long personId, Long id, BigDecimal amount) {
432	        Person person = person(sheetId, personId);
433	        // Lock the sheet first, as opening does: the new claim takes the next number.
434	        sheets.lock(sheetId);
435	        Claim claim = claim(sheetId, personId, id);
436	        settings.refuseUnless(sheetId, user, Permission.OPEN);
437	        refuseClosed(sheetId, claim.getDueBy());
438	        if (claim.getStatus() != ClaimStatus.OPEN || claim.deferredOn(sheets.today(sheetId))) {
439	            throw new SplitRefusedException("A " + claim.getStatus() + " claim cannot be split");
440	        }
441	        BigDecimal part = scaled(amount);
442	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
443	            throw new SplitRefusedException("A claim is split by an amount above 0.00 and below its own");
444	        }
445	        claim.setAmount(claim.getAmount().subtract(part));
446	        claim.unbind();
447	        Claim kept = claims.saveAndFlush(claim);
448	        LocalDate on = kept.getDate();
449	        int terms = termsFor(sheetId, person, on);
450	        LocalDate dueBy = holidays.businessDaysAfter(sheetId, on, terms);
451	        Claim split = Claim.splitOff(kept, part, dueBy, terms, nextNumber(sheetId, dueBy), user);
452	        if (periods.softClosedOn(sheetId, dueBy)) {
453	            split.markLateEntry();
454	        }
455	        Claim added = claims.saveAndFlush(split);
456	        log(sheetId, user, person, added);
457	        audit.recordOnCommit(line("CLAIM_SPLIT", sheetId, user, person, kept, kept.getNumber())
458	                + " into=" + added.getNumber());
459	        record("CLAIM_OPENED", sheetId, user, person, added);
460	        return new Split(kept, added);
461	    }
