567	    /** A steward re-settles a SETTLED claim: its settled due is frozen again at the figure it would
568	     *  have today as an OPEN claim bound by no statement (today's rates, grades, floor and late
569	     *  charge), and its status log gains a SETTLED line. Anyone else, a claim that is not SETTLED, or
570	     *  one dated in a closed period, is refused. */
571	    @Transactional
572	    public Claim resettle(String sheetId, String user, Long personId, Long id) {
573	        Person person = person(sheetId, personId);
574	        Claim claim = claim(sheetId, personId, id);
575	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
576	            throw new ResettleRefusedException(user);
577	        }
578	        if (claim.getStatus() != ClaimStatus.SETTLED) {
579	            throw new StatusChangeRefusedException(claim.getStatus(), ClaimStatus.SETTLED);
580	        }
581	        refuseClosed(sheetId, claim.getDueBy());
582	        String old = settledDueText(claim);
583	        BigDecimal figure = liveFigureOf(sheetId, person, claim, null, null);
584	        claim.setSettledDue(figure == null ? null
585	                : floored(sheetId, claim, figure.add(lateChargeOf(sheetId, person, claim, figure, true, null)), null));
586	        Claim saved = claims.saveAndFlush(claim);
587	        log(sheetId, user, person, saved);
588	        audit.recordOnCommit(line("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber())
589	                + " old=" + old + " new=" + settledDueText(saved));
590	        notifyWatchers(sheetId, user, person, saved);
591	        return saved;
