613	    private Claim move(String sheetId, String user, Long personId, Long id, Long toPersonId, boolean samePerson) {
614	        Person from = person(sheetId, personId);
615	        Person to = person(sheetId, toPersonId);
616	        // Lock the sheet first, as opening does: a numbered claim takes the next number.
617	        sheets.lock(sheetId);
618	        Claim claim = claim(sheetId, personId, id);
619	        if (!settings.allows(sheetId, user, Permission.REASSIGN)) {
620	            throw new ReassignRefusedException(user);
621	        }
622	        if (!claim.getStatus().canReassign()) {
623	            throw new MoveRefusedException("A " + claim.getStatus() + " claim cannot move to another person");
624	        }
625	        if (!samePerson && from.getId().equals(to.getId())) {
626	            throw new MoveRefusedException("The claim is already " + to.getName() + "'s");
627	        }
628	        if (claim.isCorrection()) {
629	            throw new MoveRefusedException("A correction stays with the person whose claim it corrects");
630	        }
631	        refuseClosed(sheetId, claim.getDueBy());
632	        refuseRetired(to, claim.getDate());
633	        claim.setPersonId(to.getId());
634	        if (claim.getNumber() != null) {
635	            String old = claim.getNumber();
636	            claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
637	            claims.retireNumber(sheetId, old);
638	        }
639	        claim.unbind();
640	        claims.saveAndFlush(claim);
641	        claims.relist(claim.getId());
642	        Claim saved = claim(sheetId, to.getId(), id);
643	        audit.recordOnCommit(line("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber())
644	                + " from=" + from.getName() + " to=" + to.getName());
645	        return saved;
646	    }
