655	        // Lock the sheet first, as opening does: the claim may take the next number.
656	        sheets.lock(sheetId);
657	        Claim claim = claim(sheetId, personId, id);
658	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
659	            throw new RedateForbiddenException(user);
660	        }
661	        if (!claim.getStatus().isOpen()) {
662	            throw new RedateRefusedException("A " + claim.getStatus() + " claim cannot be re-dated");
