724	    private void refuseLateOrUnstewardedVoid(String sheetId, String user, Claim claim) {
725	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
726	            throw new VoidRefusedException(user + " is not a steward: only a steward voids a settled claim");
727	        }
728	        LocalDate settledOn = logs.findByClaimIdOrderByIdAsc(claim.getId()).stream()
729	                .filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
730	                .map(ClaimLogEntry::getOn)
731	                .reduce((first, last) -> last)
732	                .orElseThrow(() -> new VoidRefusedException("Claim " + claim.getId() + " has no settlement"));
733	        if (sheets.today(sheetId).isAfter(settledOn.plusDays(VOID_WINDOW_DAYS))) {
734	            throw new VoidRefusedException("A settled claim is voided within " + VOID_WINDOW_DAYS
735	                    + " days of its settlement on " + settledOn);
736	        }
737	    }
