767	
768	    /** The number a claim opened now takes: under period numbering (set, and the sheet's today on or
769	     *  after it) the next within the period its due-by falls in, <period>-<n>, or X-<n> when it falls
770	     *  in none; otherwise the sheet's next sheet-wide number. Taken with the sheet locked. */
771	    private String nextNumber(String sheetId, LocalDate date) {
772	        if (!periodNumbering(sheetId)) {
773	            return String.valueOf(sheets.nextClaimNumber(sheetId));
774	        }
775	        String prefix = periodPrefixOf(sheetId, date);
776	        long last = Stream.concat(claims.numbers(sheetId).stream(), claims.retiredNumbers(sheetId).stream())
777	                .filter(number -> number.startsWith(prefix))
778	                .map(number -> number.substring(prefix.length()))
779	                .filter(n -> n.matches("\\d{1,18}"))
780	                .mapToLong(Long::parseLong)
781	                .max().orElse(0);
782	        return prefix + (last + 1);
783	    }
784	
785	    /** Whether period numbering is on: set, and the sheet's today on or after it. */
786	    private boolean periodNumbering(String sheetId) {
787	        LocalDate from = settings.periodNumberingFrom(sheetId);
788	        return from != null && !sheets.today(sheetId).isBefore(from);
789	    }
790	
791	    /** The prefix a period number of a claim due by a date takes: <period>- or X-. */
792	    private String periodPrefixOf(String sheetId, LocalDate date) {
793	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
794	                .filter(period -> period.contains(date))
795	                .findFirst().map(Period::getName).orElse(NO_PERIOD) + "-";
796	    }
797	
798	    /** The figure a claim shows: the due fixed when it was settled, else (unless it is PENDING, which
799	     *  no statement binds) the figure its person's last statement bound it to, else its due at the
800	     *  person's grade rate; null when it has none. */
801	    public BigDecimal figureOf(String sheetId, Person person, Claim claim) {
802	        return figureOf(sheetId, person, claim, null);
803	    }
804	
805	    /** The figure a claim (as it stood at the end of a day) showed then, the sheet's grades and rates
806	     *  as they stood then (null: the figure it shows now). */
807	    public BigDecimal figureOf(String sheetId, Person person, Claim claim, LocalDate asOf) {
808	        return figureOf(sheetId, person, claim, asOf, null);
809	    }
810	
811	    private BigDecimal figureOf(String sheetId, Person person, Claim claim, LocalDate asOf, RateOverride override) {
812	        if (claim.getSettledDue() != null) {
813	            return claim.getSettledDue();
814	        }
815	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue()
816	                : liveFigureOf(sheetId, person, claim, asOf, override);
817	    }
818	
819	    /** The due a claim shows: a settled claim's frozen due; otherwise the greater of the sheet's floor in
820	     *  force on its date (none for a correction) and its figure plus its late charge (none while it is
821	     *  deferred: it is not overdue then); null when it has no figure. */
822	    public BigDecimal dueOf(String sheetId, Person person, Claim claim) {
823	        return dueOf(sheetId, person, claim, null);
824	    }
825	
826	    /** The due a claim (as it stood at the end of a day) showed then: that day stands in for the
827	     *  sheet's today, and the floor, late percent, grades and rates are as they stood then (null: the
828	     *  due it shows now). */
829	    public BigDecimal dueOf(String sheetId, Person person, Claim claim, LocalDate asOf) {
830	        return dueOf(sheetId, person, claim, asOf, null);
831	    }
832	
833	    /** The due a claim would show were a grade's rate the one given on every date (null: as the rates
834	     *  stand). */
835	    private BigDecimal dueOf(String sheetId, Person person, Claim claim, LocalDate asOf, RateOverride override) {
836	        if (claim.getSettledDue() != null) {
837	            return claim.getSettledDue();
838	        }
839	        BigDecimal figure = figureOf(sheetId, person, claim, asOf, override);
840	        boolean open = claim.getStatus().isOpen() && !claim.deferredOn(todayOr(sheetId, asOf));
841	        return figure == null ? null
842	                : floored(sheetId, claim, figure.add(lateChargeOf(sheetId, person, claim, figure, open, asOf)), asOf);
843	    }
844	
845	    /** The day that stands for the sheet's today: the given one, else the sheet's today. */
846	    private LocalDate todayOr(String sheetId, LocalDate asOf) {
847	        return asOf != null ? asOf : sheets.today(sheetId);
848	    }
849	
850	    /** A due raised to the sheet's floor in force on the claim's date, unless the claim is a correction. */
851	    private BigDecimal floored(String sheetId, Claim claim, BigDecimal due, LocalDate asOf) {
852	        return claim.isCorrection() ? due : due.max(settings.floor(sheetId, claim.getDate(), asOf));
853	    }
854	
855	    /** The date a claim is overdue after: its due-by plus the grace days in force on its date for the
856	     *  person's grade in force on its date (as they stood at the end of a day; null: as they stand now). */
857	    public LocalDate overdueFrom(String sheetId, Person person, Claim claim, LocalDate asOf) {
858	        String grade = grades.gradeOn(person.getId(), claim.getDate(), asOf);
859	        return claim.getDueBy().plusDays(settings.graceFor(sheetId, grade, claim.getDate(), asOf));
860	    }
861	
862	    /** The late charge on a claim with a figure: none unless it is OPEN or PENDING and overdue (its due-by
863	     *  plus its grace, see overdueFrom, is before the sheet's today) or a correction, else the late percent of
864	     *  the figure for every 30-day boundary it is overdue past (its due-by plus its grace plus 30, 60, 90 ...
865	     *  days), compounding: the late percent in force on that boundary date of the figure plus the charges
866	     *  of the boundaries before it, rounded to two decimals as the claim's date decides (see roundingOf), the
867	     *  charges added up. Never bound by a statement: it follows the
868	     *  sheet's today. Whether the claim counts as open is given, so a re-settle can charge a SETTLED
869	     *  claim as if it were still OPEN. */
870	    private BigDecimal lateChargeOf(String sheetId, Person person, Claim claim, BigDecimal figure, boolean open,
871	            LocalDate asOf) {
872	        BigDecimal none = BigDecimal.ZERO.setScale(2);
873	        if (!open || claim.isCorrection()) {
874	            return none;
875	        }
876	        LocalDate from = overdueFrom(sheetId, person, claim, asOf);
877	        long days = ChronoUnit.DAYS.between(from, todayOr(sheetId, asOf));
878	        if (days < 30) {
879	            return none;
880	        }
881	        RoundingMode rounding = roundingOf(sheetId, claim, asOf);
882	        BigDecimal charge = none;
883	        for (long boundary = 1; boundary <= days / 30; boundary++) {
884	            BigDecimal pct = settings.latePct(sheetId, from.plusDays(30 * boundary), asOf);
885	            if (pct.signum() != 0) {
886	                charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding));
887	            }
888	        }
889	        return charge;
890	    }
891	
892	    /** The due on a claim at the rate in force on the claim's date for the person's grade in force
893	     *  on the claim's date: amount times rate
894	     *  divided by 100, rounded to two decimals as the claim's date decides (see roundingOf); the floor is
895	     *  not applied here (see dueOf); null when no rate applies. */
896	    private BigDecimal liveFigureOf(String sheetId, Person person, Claim claim, LocalDate asOf,
897	            RateOverride override) {
898	        BigDecimal amount = claim.getAmount();
899	        RoundingMode rounding = roundingOf(sheetId, claim, asOf);
900	        String grade = grades.gradeOn(person.getId(), claim.getDate(), asOf);
901	        Optional<BigDecimal> inForce = override != null && override.grade().equals(grade) ? Optional.of(override.rate())
902	                : rates.rateOn(sheetId, grade, claim.getDate(), asOf).map(Rate::getRate);
903	        return inForce
904	                .map(rate -> amount.multiply(rate).movePointLeft(2).setScale(2, rounding))
905	                .orElse(null);
906	    }
907	
908	    /** A grade's rate taken to apply on every date in place of the rates set for it. */
909	    private record RateOverride(String grade, BigDecimal rate) {
910	    }
911	
912	    /** What a rate preview finds: how many claims would show a different due, and the sum of the
913	     *  differences (new due minus current due). */
914	    public record RatePreview(int count, BigDecimal diff) {
915	    }
916	
917	    /** How the OPEN and PENDING claims of people on a grade (the grade in force on the claim's date)
918	     *  would change were the rate given the grade's rate on every date: how many would show a different
919	     *  due and the sum of the differences (a due of n/a counts as 0.00). A claim a statement binds keeps
920	     *  its figure. Nothing is saved. */
921	    @Transactional(readOnly = true)
922	    public RatePreview previewRate(String sheetId, String grade, BigDecimal rate) {
923	        RateOverride override = new RateOverride(grade, rate);
924	        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
925	                .collect(Collectors.toMap(Person::getId, person -> person));
926	        int count = 0;
927	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
928	        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
929	            Person person = byId.get(claim.getPersonId());
930	            if (person == null || !claim.getStatus().isOpen()
931	                    || !grade.equals(grades.gradeOn(person.getId(), claim.getDate(), null))) {
932	                continue;
933	            }
934	            BigDecimal now = dueOf(sheetId, person, claim, null);
935	            BigDecimal then = dueOf(sheetId, person, claim, null, override);
936	            BigDecimal was = now == null ? BigDecimal.ZERO : now;
937	            BigDecimal will = then == null ? BigDecimal.ZERO : then;
938	            if ((now == null) != (then == null) || was.compareTo(will) != 0) {
939	                count++;
940	                diff = diff.add(will.subtract(was));
941	            }
942	        }
943	        return new RatePreview(count, diff.setScale(2, RoundingMode.HALF_UP));
944	    }
945	
946	    /** The date a claim's live figures round by: its own, or for a correction the date of the claim
947	     *  it corrects. */
948	    public LocalDate roundsBy(String sheetId, Claim claim) {
949	        if (!claim.isCorrection() || claim.getCorrects() == null) {
950	            return claim.getDate();
951	        }
952	        return claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects())
953	                .map(Claim::getDate).orElse(claim.getDate());
954	    }
955	
956	    /** How a claim's live figures round: by the sheet's policy date against the date it rounds by. */
957	    private RoundingMode roundingOf(String sheetId, Claim claim, LocalDate asOf) {
958	        return settings.roundingOn(sheetId, roundsBy(sheetId, claim), asOf);
959	    }
960	
961	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit; a due of n/a
962	     *  is within any limit, and a steward settles anything. */
963	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
964	        BigDecimal limit = settings.clerkLimit(sheetId);
965	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
966	            return false;
967	        }
968	        return settings.roleOf(sheetId, user) == Role.CLERK;
969	    }
970	
971	    /** A claim whose due is above the proof threshold in force on its date (its person's grade's in
972	     *  force then when one is set, else the sheet's) cannot be settled or approved while it has no
973	     *  proofs; a due of n/a, or no threshold, asks for none. */
974	    private void refuseUnproved(String sheetId, Person person, Claim claim, BigDecimal due) {
975	        String grade = grades.gradeOn(person.getId(), claim.getDate());
976	        BigDecimal threshold = settings.proofThresholdFor(sheetId, grade, claim.getDate());
977	        if (claim.getProofs() == 0 && threshold != null && due != null && due.compareTo(threshold) > 0) {
978	            throw new ProofRequiredException(due, threshold);
979	        }
980	    }
981	
982	    /** A claim whose due is above the note threshold in force on its date cannot be opened while its
983	     *  note is empty; a due of n/a, or no threshold, asks for none. */
984	    private void refuseUnnoted(String sheetId, Person person, Claim claim) {
985	        BigDecimal threshold = settings.noteThreshold(sheetId, claim.getDate());
986	        if (threshold == null || (claim.getNote() != null && !claim.getNote().isBlank())) {
987	            return;
988	        }
989	        BigDecimal due = dueOf(sheetId, person, claim);
990	        if (due != null && due.compareTo(threshold) > 0) {
991	            throw new NoteRequiredException(due, threshold);
992	        }
993	    }
994	
995	    /** A negative amount (a correction) must name the number of a SETTLED claim of the same person;
996	     *  any other amount names none. */
997	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
998	        if (amount.signum() >= 0) {
999	            if (corrects != null) {
1000	                throw new CorrectionRefusedException("Only a negative amount corrects a claim");
1001	            }
1002	            return;
1003	        }
1004	        if (corrects == null) {
1005	            throw new CorrectionRefusedException("A negative amount must name the claim it corrects");
1006	        }
1007	        boolean settled = claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
1008	                .map(c -> c.getStatus() == ClaimStatus.SETTLED).orElse(false);
1009	        if (!settled) {
1010	            throw new CorrectionRefusedException("No SETTLED claim " + corrects + " of this person to correct");
1011	        }
1012	    }
1013	
1014	    /** Whether a claim on the sheet other than the given one (null: any) already uses the reference,
1015	     *  without regard to case; a null reference is never in use. */
1016	    public boolean refInUse(String sheetId, String ref, Long exceptId) {
1017	        return ref != null && claims.refInUse(sheetId, Claim.keyOf(ref), exceptId);
1018	    }
1019	
1020	    /** A reference another claim on the sheet already uses cannot be given again. */
1021	    private void refuseRefInUse(String sheetId, String ref, Long exceptId) {
1022	        if (refInUse(sheetId, ref, exceptId)) {
1023	            throw new RefInUseException("The reference " + ref + " is already used on the sheet");
1024	        }
1025	    }
1026	
1027	    /** A claim whose due-by falls inside a closed period cannot be added, edited, opened, settled or voided. */
1028	    private void refuseClosed(String sheetId, LocalDate dueBy) {
1029	        if (periods.closedOn(sheetId, dueBy)) {
1030	            throw new PeriodClosedException("A claim due by " + dueBy + " falls in a closed period");
1031	        }
1032	    }
1033	
1034	    /** A claim dated after its person's retirement date, or after the from and before the to of a past
1035	     *  retirement of theirs, cannot be added or moved there. */
1036	    private void refuseRetired(Person person, LocalDate date) {
1037	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
1038	            throw new PersonRetiredException(person.getName(), person.getRetiredFrom(), date);
1039	        }
1040	        for (PersonRetirement past : retirements.findByPersonIdOrderByIdAsc(person.getId())) {
1041	            if (past.covers(date)) {
1042	                throw new PersonRetiredException(person.getName(), past.getFrom(), date);
1043	            }
1044	        }
1045	    }
1046	
1047	    private Person person(String sheetId, Long personId) {
1048	        return people.findByIdAndSheetId(personId, sheetId)
1049	                .orElseThrow(() -> new NoSuchElementException("No person " + personId + " on sheet " + sheetId));
1050	    }
1051	
1052	    /** One NOTIFY line for each user watching the claim's person, in the order they started watching. */
1053	    private void notifyWatchers(String sheetId, String user, Person person, Claim claim) {
1054	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
1055	            audit.recordOnCommit("NOTIFY sheet=" + sheetId + " by=" + user + " user=" + watch.getUser()
1056	                    + " person=" + person.getName() + " number=" + claim.getNumber());
1057	        }
1058	    }
1059	
1060	    private void record(String event, String sheetId, String user, Person person, Claim claim) {
1061	        record(event, sheetId, user, person, claim, claim.getNumber());
1062	    }
1063	
1064	    /** One audit line about a claim; a claim with a number carries it at the end. */
1065	    private void record(String event, String sheetId, String user, Person person, Claim claim, String number) {
1066	        audit.recordOnCommit(line(event, sheetId, user, person, claim, number));
1067	    }
1068	
1069	    private static String line(String event, String sheetId, String user, Person person, Claim claim, String number) {
1070	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
1071	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
1072	                + (number != null ? " number=" + number : "");
1073	    }
1074	
1075	    private static BigDecimal scaled(BigDecimal amount) {
1076	        return amount.setScale(2, RoundingMode.UNNECESSARY);
1077	    }
1078	
1079	    /** A claim number as typed: trimmed, null when blank. */
1080	    private static String numberOf(String number) {
1081	        return number == null || number.isBlank() ? null : number.trim();
1082	    }
1083	
1084	    /** Tags as typed, comma separated: each trimmed and in lower case, blanks and repeats dropped,
1085	     *  sorted. */
1086	    public static SortedSet<String> tagsOf(String tags) {
1087	        SortedSet<String> out = new TreeSet<>();
1088	        if (tags != null) {
1089	            for (String tag : tags.split(",")) {
1090	                if (!tag.isBlank()) {
1091	                    out.add(tag.trim().toLowerCase(Locale.ROOT));
1092	                }
1093	            }
1094	        }
1095	        return out;
1096	    }
1097	
1098	    /** Every tag ever used on the sheet, sorted. */
1099	    public List<String> tagsUsed(String sheetId) {
1100	        return claims.tagsUsed(sheetId);
1101	    }
1102	
1103	    /** Keep the claim's tags on the sheet's list of the tags ever used. */
1104	    private void useTags(String sheetId, Claim claim) {
1105	        claim.getTags().forEach(tag -> claims.useTag(sheetId, tag));
1106	    }
1107	
1108	    /** An external reference as typed: trimmed, null when blank. */
1109	    public static String refOf(String ref) {
1110	        return ref == null || ref.isBlank() ? null : ref.trim();
1111	    }
1112	
1113	    private static String noteOf(String note) {
1114	        return note == null ? "" : note.trim();
1115	    }
1116	
1117	    /** The terms in business days a claim of the person dated on a date takes: the person's own, else their
1118	     *  grade's in force then, else the sheet's. */
1119	    private int termsFor(String sheetId, Person person, LocalDate on) {
1120	        return person.getTerms() != null ? person.getTerms()
1121	                : settings.termsFor(sheetId, grades.gradeOn(person.getId(), on), on);
1122	    }
1123	}
