43	    /** A claim as the screen shows it; the amount and the due fixed on settling (null when none
44	     *  was) are strings with two decimals; openedBy is null for a claim never opened; stated tells
45	     *  whether a statement bound the claim, statedDue the figure it bound it to (null when none);
46	     *  corrects is the number of the claim a correction corrects (null when it is not one); roundsBy
47	     *  is the date its live figures round by against the sheet's policy date (its own date, or for a
48	     *  correction the date of the claim it corrects); dueBy is the date it is due by, fixed when it was
49	     *  added; log is its status log, oldest first, one line per status it has had; deferredUntil is
50	     *  the date it was deferred until (null when it never was); proofs is how many proofs were added
51	     *  to it; splitFrom is the number of the claim it was split off (null when it was not); lockedBy is
52	     *  the user whose open editor locks it (null when no one's does); lateEntry is whether it was
53	     *  added while its period was soft-closed; remindedOn is the last day a reminder was written for it
54	     *  (null when none was); ref is its external reference (null when it has none); tags are its tags,
55	     *  sorted (empty when it has none); voidReason is the reason it was voided with (null when none
56	     *  was given); comments are its comments, oldest first, each as <user> on <date>: <text>; batch
57	     *  is the number of the settle batch that settled it (null when a bulk settle did not). */
58	    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note,
59	            ClaimStatus status, String number, String settledDue, String openedBy, boolean stated,
60	            String statedDue, String corrects, LocalDate roundsBy, LocalDate dueBy, List<String> log,
61	            LocalDate deferredUntil, int proofs, String splitFrom, String lockedBy, boolean lateEntry,
62	            LocalDate remindedOn, String ref, List<String> tags, String voidReason, List<String> comments,
63	            Long batch) {
64	        public static ClaimView of(Claim claim, LocalDate roundsBy, List<String> log, List<String> comments) {
65	            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
66	                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
67	                    claim.getSettledDue() != null ? claim.getSettledDue().toPlainString() : null,
68	                    claim.getOpenedBy(), claim.isStated(),
69	                    claim.getStatedDue() != null ? claim.getStatedDue().toPlainString() : null,
70	                    claim.getCorrects(), roundsBy, claim.getDueBy(), log, claim.getDeferredUntil(),
71	                    claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(), claim.isLateEntry(),
72	                    claim.getRemindedOn(), claim.getRef(), claim.getTags(),
73	                    claim.getVoidReason(), comments, claim.getBatch());
74	        }
75	    }
