174	    /** The sheet's claims, newest first: as they stand now, or as they stood at the end of the
175	     *  screen's as-of date (those added by then, each with its status log up to then). */
176	    @GetMapping("/claims")
177	    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
178	            @RequestHeader(value = AsOf.HEADER, required = false) String asOfHeader) {
179	        String sheet = sheetId.trim();
180	        LocalDate asOf = AsOf.parse(asOfHeader);
181	        Map<Long, List<String>> logs = service.logsOf(sheet, asOf);
182	        Map<Long, List<String>> comments = service.commentsOf(sheet, asOf);
183	        List<Claim> claims = asOf == null ? service.list(sheet) : history.claims(service.list(sheet), asOf);
184	        return claims.stream()
185	                .map(claim -> ClaimView.of(claim, service.roundsBy(sheet, claim), logs.getOrDefault(claim.getId(), List.of()),
186	                        comments.getOrDefault(claim.getId(), List.of())))
187	                .toList();
188	    }
