440	     *  approving a claim above the proof threshold with no proofs, or opening a claim above the note
441	     *  threshold with an empty note, or a split the claim or amount does
442	     *  not allow, or a void of a SETTLED claim by anyone but a steward or after its void window, or a
443	     *  void without a reason from the sheet's list while it has one, or a
444	     *  re-date of a claim that is not OPEN or PENDING, or opening or saving the editor of a claim
445	     *  another user's editor locks, or a reminder of a claim that is not OPEN or PENDING or was already
446	     *  reminded on the sheet's today, or an empty comment, or a delete of a claim that is not a DRAFT or
447	     *  a restore of one not deleted on the sheet's today, is refused. */
448	    @ExceptionHandler({VoidRefusedException.class, StatusChangeRefusedException.class, ClaimNotEditableException.class, CorrectionRefusedException.class,
449	            PeriodClosedException.class, PersonRetiredException.class, MoveRefusedException.class,
450	            DeferRefusedException.class, ProofRefusedException.class, ProofRequiredException.class, NoteRequiredException.class,
451	            SplitRefusedException.class, RedateRefusedException.class, ClaimLockedException.class,
452	            RemindRefusedException.class, CommentRefusedException.class, DeleteRefusedException.class, RefInUseException.class, DataIntegrityViolationException.class})
453	    @ResponseStatus(HttpStatus.CONFLICT)
454	    public void refused() {
455	    }
456	
457	    /** The user who opened a claim cannot settle or approve it, only a steward approves or rejects a
458	     *  PENDING claim, re-settles a SETTLED one or re-dates a claim, and only a role the sheet's permission matrix allows
459	     *  opens, settles, voids or moves a claim to another person. */
460	    @ExceptionHandler({OwnClaimSettleRefusedException.class, ApprovalRefusedException.class, ReassignRefusedException.class,
461	            ResettleRefusedException.class, PermissionRefusedException.class, RedateForbiddenException.class})
462	    @ResponseStatus(HttpStatus.FORBIDDEN)
463	    public void ownClaim() {
464	    }
465	
466	    @ExceptionHandler(NoSuchElementException.class)
467	    @ResponseStatus(HttpStatus.NOT_FOUND)
468	    public void notFound() {
469	    }
470	
471	    /** An amount that is not a number or a date that is not a real yyyy-mm-dd date is refused. */
472	    @ExceptionHandler(HttpMessageNotReadableException.class)
473	    @ResponseStatus(HttpStatus.BAD_REQUEST)
474	    public void unreadable() {
475	    }
