package net.officefloor.hq.app.claim;

import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.AsOf;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.claimtemplate.ClaimTemplate;
import net.officefloor.hq.app.claimtemplate.ClaimTemplateService;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.setting.PermissionRefusedException;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.PersonRetiredException;
import net.officefloor.hq.app.rollup.RollupService;
import java.util.NoSuchElementException;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimController {

    /** A claim as the screen shows it; the amount and the due fixed on settling (null when none
     *  was) are strings with two decimals; openedBy is null for a claim never opened; stated tells
     *  whether a statement bound the claim, statedDue the figure it bound it to (null when none);
     *  corrects is the number of the claim a correction corrects (null when it is not one); roundsBy
     *  is the date its live figures round by against the sheet's policy date (its own date, or for a
     *  correction the date of the claim it corrects); dueBy is the date it is due by, fixed when it was
     *  added; log is its status log, oldest first, one line per status it has had; deferredUntil is
     *  the date it was deferred until (null when it never was); proofs is how many proofs were added
     *  to it; splitFrom is the number of the claim it was split off (null when it was not); lockedBy is
     *  the user whose open editor locks it (null when no one's does); lateEntry is whether it was
     *  added while its period was soft-closed; remindedOn is the last day a reminder was written for it
     *  (null when none was); ref is its external reference (null when it has none); tags are its tags,
     *  sorted (empty when it has none); voidReason is the reason it was voided with (null when none
     *  was given); comments are its comments, oldest first, each as <user> on <date>: <text>; batch
     *  is the number of the settle batch that settled it (null when a bulk settle did not). */
    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note,
            ClaimStatus status, String number, String settledDue, String openedBy, boolean stated,
            String statedDue, String corrects, LocalDate roundsBy, LocalDate dueBy, List<String> log,
            LocalDate deferredUntil, int proofs, String splitFrom, String lockedBy, boolean lateEntry,
            LocalDate remindedOn, String ref, List<String> tags, String voidReason, List<String> comments,
            Long batch) {
        public static ClaimView of(Claim claim, LocalDate roundsBy, List<String> log, List<String> comments) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() != null ? claim.getSettledDue().toPlainString() : null,
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() != null ? claim.getStatedDue().toPlainString() : null,
                    claim.getCorrects(), roundsBy, claim.getDueBy(), log, claim.getDeferredUntil(),
                    claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(), claim.isLateEntry(),
                    claim.getRemindedOn(), claim.getRef(), claim.getTags(),
                    claim.getVoidReason(), comments, claim.getBatch());
        }
    }

    /** A claim's fields: an amount with up to two decimals (a negative one is a correction), a date
     *  (blank takes the sheet's today), a note (may be empty) and, for a correction, the number of
     *  the claim it corrects, an external reference (blank: none) and tags, comma separated (blank:
     *  none). */
    public record ClaimRequest(
            @NotNull @Digits(integer = 10, fraction = 2) BigDecimal amount,
            LocalDate date,
            @Size(max = 2000) String note,
            @Size(max = 255) String corrects,
            @Size(max = 255) String ref,
            @Size(max = 2000) String tags) {
    }

    /** The name of the sheet's claim template a claim is added from. */
    public record FromTemplateRequest(@NotBlank @Size(max = 255) String template) {
    }

    /** The date an OPEN claim is deferred until. */
    public record DeferRequest(@NotNull LocalDate until) {
    }

    /** The reason a claim is voided with, chosen from the sheet's list; blank or absent for none. */
    public record VoidRequest(@Size(max = 255) String reason) {
    }

    /** A comment on a claim: its text, which must not be blank. */
    public record CommentRequest(@Size(max = 2000) String text) {
    }

    /** Why a steward rejects a PENDING claim. */
    public record RejectRequest(@NotBlank @Size(max = 500) String reason) {
    }

    /** The new date of an OPEN or PENDING claim. */
    public record RedateRequest(@NotNull LocalDate date) {
    }

    /** The amount split off an OPEN claim. */
    public record SplitRequest(@NotNull @Digits(integer = 10, fraction = 2) BigDecimal amount) {
    }

    /** What a split did: the claim that kept the rest of its amount, and the new claim split off it. */
    public record SplitView(ClaimView kept, ClaimView added) {
    }

    /** The person on the sheet a claim moves to. */
    public record ReassignRequest(@NotNull Long toPersonId) {
    }

    /** The claims selected to open together. */
    public record BulkOpenRequest(@NotNull @Size(max = 10000) Set<@NotNull Long> claimIds) {
    }

    /** What a bulk open did: the claims it opened, in the order it numbered them, and how many of the
     *  selected claims it refused. */
    public record BulkOpenView(List<ClaimView> opened, int refused) {
    }

    /** The claims selected to settle together. */
    public record BulkSettleRequest(@NotNull @Size(max = 10000) Set<@NotNull Long> claimIds) {
    }

    /** What a bulk settle did: the claims it settled (SETTLED, or PENDING a steward's approval), in
     *  list order, how many of the selected claims it refused, and the number of the batch it made
     *  (null when it settled none). */
    public record BulkSettleView(List<ClaimView> settled, int refused, Long batch) {
    }

    /** The claims selected to move together, and the person on the sheet they move to. */
    public record BulkReassignRequest(@NotNull @Size(max = 10000) Set<@NotNull Long> claimIds, @NotNull Long toPersonId) {
    }

    /** What a bulk move did: the claims it moved, in list order, and how many of the selected claims
     *  it refused. */
    public record BulkReassignView(List<ClaimView> reassigned, int refused) {
    }

    private final ClaimService service;
    private final RollupService rollups;
    private final BulkOpenService bulkOpen;
    private final BulkSettleService bulkSettle;
    private final BulkReassignService bulkReassign;
    private final History history;
    private final ClaimTemplateService templates;

    public ClaimController(ClaimService service, RollupService rollups, BulkOpenService bulkOpen,
            BulkSettleService bulkSettle, BulkReassignService bulkReassign, History history,
            ClaimTemplateService templates) {
        this.templates = templates;
        this.bulkReassign = bulkReassign;
        this.history = history;
        this.service = service;
        this.rollups = rollups;
        this.bulkOpen = bulkOpen;
        this.bulkSettle = bulkSettle;
    }

    /** The sheet's claims, newest first: as they stand now, or as they stood at the end of the
     *  screen's as-of date (those added by then, each with its status log up to then). */
    @GetMapping("/claims")
    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(value = AsOf.HEADER, required = false) String asOfHeader) {
        String sheet = sheetId.trim();
        LocalDate asOf = AsOf.parse(asOfHeader);
        Map<Long, List<String>> logs = service.logsOf(sheet, asOf);
        Map<Long, List<String>> comments = service.commentsOf(sheet, asOf);
        List<Claim> claims = asOf == null ? service.list(sheet) : history.claims(service.list(sheet), asOf);
        return claims.stream()
                .map(claim -> ClaimView.of(claim, service.roundsBy(sheet, claim), logs.getOrDefault(claim.getId(), List.of()),
                        comments.getOrDefault(claim.getId(), List.of())))
                .toList();
    }

    /** Every tag ever used on the sheet's claims, sorted. */
    @GetMapping("/claim-tags")
    public List<String> tags(@PathVariable @NotBlank @Size(max = 200) String sheetId) {
        return service.tagsUsed(sheetId.trim());
    }

    /** Add a claim for a person. */
    @PostMapping("/people/{personId}/claims")
    @ResponseStatus(HttpStatus.CREATED)
    public ClaimView add(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated ClaimRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return view(sheet, rollups.track(sheet, by, () -> service.add(sheet, by, personId, request.amount(),
                request.date(), request.note(), request.corrects(), request.ref(), request.tags())));
    }

    /** Add a DRAFT claim for a person from a claim template: its amount and note as they are now,
     *  with no date, by every rule of adding one from the claim form. */
    @PostMapping("/people/{personId}/claims/from-template")
    @ResponseStatus(HttpStatus.CREATED)
    public ClaimView addFromTemplate(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated FromTemplateRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        ClaimTemplate template = templates.get(sheet, request.template());
        return view(sheet, rollups.track(sheet, by, () -> service.add(sheet, by, personId, template.getAmount(),
                null, template.getNote(), null, null, null)));
    }

    /** Change a DRAFT claim's amount, date and note. */
    @PutMapping("/people/{personId}/claims/{id}")
    public ClaimView update(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated ClaimRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return view(sheet, rollups.track(sheet, by, () -> service.update(sheet, by, personId, id,
                request.amount(), request.date(), request.note(), request.corrects(), request.ref(), request.tags())));
    }

    /** Open a claim's editor: lock the DRAFT claim to the user until they save or cancel it. */
    @PostMapping("/people/{personId}/claims/{id}/lock")
    public ClaimView lock(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String sheet = sheetId.trim();
        return view(sheet, service.lock(sheet, SignedInUser.decode(user), personId, id));
    }

    /** Cancel a claim's editor: release the user's lock on it. */
    @DeleteMapping("/people/{personId}/claims/{id}/lock")
    public ClaimView unlock(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String sheet = sheetId.trim();
        return view(sheet, service.unlock(sheet, SignedInUser.decode(user), personId, id));
    }

    /** Open a DRAFT claim. */
    @PostMapping("/people/{personId}/claims/{id}/open")
    public ClaimView open(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return changeStatus(sheetId, user, personId, id, ClaimStatus.OPEN);
    }

    /** Open the selected claims that can be opened, numbered in list order; the rest are refused
     *  and left as they are. */
    @PostMapping("/claims/open")
    public BulkOpenView openAll(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated BulkOpenRequest request) {
        String sheet = sheetId.trim();
        BulkOpenService.Result result = bulkOpen.open(sheet, SignedInUser.decode(user), request.claimIds());
        return new BulkOpenView(result.opened().stream().map(claim -> view(sheet, claim)).toList(), result.refused());
    }

    /** Settle an OPEN claim; the user who opened it cannot. A clerk settling one whose due is above
     *  the clerk limit leaves it PENDING a steward's approval. */
    @PostMapping("/people/{personId}/claims/{id}/settle")
    public ClaimView settle(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return changeStatus(sheetId, user, personId, id, ClaimStatus.SETTLED);
    }

    /** Settle the selected claims that can be settled, in list order, each by the rules of settling
     *  one; the rest are refused and left as they are. */
    @PostMapping("/claims/settle")
    public BulkSettleView settleAll(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated BulkSettleRequest request) {
        String sheet = sheetId.trim();
        BulkSettleService.Result result = bulkSettle.settle(sheet, SignedInUser.decode(user), request.claimIds());
        return new BulkSettleView(result.settled().stream().map(claim -> view(sheet, claim)).toList(), result.refused(),
                result.batch());
    }

    /** Approve a PENDING claim: a steward other than whoever opened it settles it. */
    @PostMapping("/people/{personId}/claims/{id}/approve")
    public ClaimView approve(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return view(sheet, rollups.track(sheet, by, () -> service.approve(sheet, by, personId, id)));
    }

    /** Reject a PENDING claim with a reason: a steward sends it back to OPEN. */
    @PostMapping("/people/{personId}/claims/{id}/reject")
    public ClaimView reject(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated RejectRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return view(sheet, rollups.track(sheet, by, () -> service.reject(sheet, by, personId, id, request.reason())));
    }

    /** Re-settle a SETTLED claim at the figure it would have today: a steward only. */
    @PostMapping("/people/{personId}/claims/{id}/resettle")
    public ClaimView resettle(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return view(sheet, rollups.track(sheet, by, () -> service.resettle(sheet, by, personId, id)));
    }

    /** Move a DRAFT, OPEN or PENDING claim to another person: a steward only. */
    @PostMapping("/people/{personId}/claims/{id}/reassign")
    public ClaimView reassign(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated ReassignRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return view(sheet, rollups.track(sheet, by,
                () -> service.reassign(sheet, by, personId, id, request.toPersonId())));
    }

    /** Move the selected claims to a person, in list order, each by the rules of moving one; the rest
     *  are refused and left as they are. */
    @PostMapping("/claims/reassign")
    public BulkReassignView reassignAll(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated BulkReassignRequest request) {
        String sheet = sheetId.trim();
        BulkReassignService.Result result = bulkReassign.reassign(sheet, SignedInUser.decode(user), request.claimIds(),
                request.toPersonId());
        return new BulkReassignView(result.reassigned().stream().map(claim -> view(sheet, claim)).toList(),
                result.refused());
    }

    /** Defer an OPEN claim until a date after the sheet's today. */
    @PostMapping("/people/{personId}/claims/{id}/defer")
    public ClaimView defer(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated DeferRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return view(sheet, rollups.track(sheet, by, () -> service.defer(sheet, by, personId, id, request.until())));
    }

    /** Remind an OPEN or PENDING claim, once per sheet's today. */
    @PostMapping("/people/{personId}/claims/{id}/remind")
    public ClaimView remind(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String sheet = sheetId.trim();
        return view(sheet, service.remind(sheet, SignedInUser.decode(user), personId, id));
    }

    /** Re-date an OPEN or PENDING claim: a steward only. */
    @PostMapping("/people/{personId}/claims/{id}/redate")
    public ClaimView redate(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated RedateRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return view(sheet, rollups.track(sheet, by, () -> service.redate(sheet, by, personId, id, request.date())));
    }

    /** Split an amount off an OPEN claim into a new OPEN claim. */
    @PostMapping("/people/{personId}/claims/{id}/split")
    @ResponseStatus(HttpStatus.CREATED)
    public SplitView split(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated SplitRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        ClaimService.Split split = rollups.track(sheet, by,
                () -> service.split(sheet, by, personId, id, request.amount()));
        return new SplitView(view(sheet, split.kept()), view(sheet, split.added()));
    }

    /** Add a proof to a claim that is not SETTLED or VOID. */
    @PostMapping("/people/{personId}/claims/{id}/proof")
    public ClaimView addProof(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return view(sheet, service.addProof(sheet, by, personId, id));
    }

    /** Comment on a claim, kept with the user and the sheet's today; an empty comment is refused. */
    @PostMapping("/people/{personId}/claims/{id}/comments")
    public ClaimView addComment(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated CommentRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return view(sheet, service.addComment(sheet, by, personId, id, request.text()));
    }

    /** Void a DRAFT, OPEN or PENDING claim, or (a steward, within 7 days of its settlement) a SETTLED
     *  one; while the sheet's list of void reasons is not empty, with a reason chosen from it. */
    @PostMapping("/people/{personId}/claims/{id}/void")
    public ClaimView voidClaim(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody(required = false) @Validated VoidRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        String reason = request == null ? null : request.reason();
        return view(sheet, rollups.track(sheet, by,
                () -> service.changeStatus(sheet, by, personId, id, ClaimStatus.VOID, reason)));
    }

    /** Delete a DRAFT claim: it counts nowhere until restored. */
    @PostMapping("/people/{personId}/claims/{id}/delete")
    public ClaimView delete(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return view(sheet, rollups.track(sheet, by, () -> service.delete(sheet, by, personId, id)));
    }

    /** Restore a DELETED claim to a DRAFT, on the sheet's today it was deleted. */
    @PostMapping("/people/{personId}/claims/{id}/restore")
    public ClaimView restore(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return view(sheet, rollups.track(sheet, by, () -> service.restore(sheet, by, personId, id)));
    }

    private ClaimView changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return view(sheet, rollups.track(sheet, by, () -> service.changeStatus(sheet, by, personId, id, to)));
    }

    private ClaimView view(String sheet, Claim claim) {
        return ClaimView.of(claim, service.roundsBy(sheet, claim), service.logOf(claim.getId()),
                service.commentsOf(claim.getId()));
    }

    /** A status change the claim's status does not allow, an edit of a claim that is not a DRAFT,
     *  any change to a claim dated in a closed period, a claim dated after its person retired, or a
     *  correction that does not name a SETTLED claim of its person, a move the claim does not allow,
     *  a deferral the claim does not allow, a proof added to a SETTLED or VOID claim, or settling or
     *  approving a claim above the proof threshold with no proofs, or opening a claim above the note
     *  threshold with an empty note, or a split the claim or amount does
     *  not allow, or a void of a SETTLED claim by anyone but a steward or after its void window, or a
     *  void without a reason from the sheet's list while it has one, or a
     *  re-date of a claim that is not OPEN or PENDING, or opening or saving the editor of a claim
