6	import { NO_RATE, PersonGrade, Rate, RateStore, dueCents, gradeOn, rateOn } from '../rates/rates';
7	import { VoidReasonStore } from '../void-reasons/void-reasons';
8	import { ClaimTemplateStore } from '../claim-templates/claim-templates';
9	
10	/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; an OPEN claim a clerk settles above
11	 *  the clerk limit is PENDING until a steward approves it (SETTLED) or rejects it (OPEN again); a
12	 *  DRAFT, OPEN or PENDING claim can be VOID, and a steward may void a SETTLED one within 7 days of
13	 *  its settlement. A DRAFT can be DELETED, counting nowhere, and restored to a DRAFT on the same
14	 *  sheet-today. */
15	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED';
