81	/** Whether a claim is deferred on the sheet's today: it is OPEN and today is before the date it was
82	 *  deferred until. From that date on it is an OPEN claim like any other. */
83	export function deferred(claim: Claim, today: string | null): boolean {
84	  return claim.status === 'OPEN' && claim.deferredUntil !== null && today !== null && today < claim.deferredUntil;
85	}
86	
87	/** The status a claim had at the end of a day, as its status log records it: the last status it
88	 *  moved to on or before that day; null when it was added after it. */
89	export function statusAsOf(claim: Claim, day: string): ClaimStatus | null {
90	  let status: ClaimStatus | null = null;
91	  for (const line of claim.log) {
92	    const match = /^(\S+) by .* on (\d{4}-\d{2}-\d{2}) due=\S+$/.exec(line);
93	    if (match && match[2] <= day) status = match[1] as ClaimStatus;
94	  }
95	  return status;
96	}
