98	/** Whether a claim is a correction: its amount is negative. */
99	export function isCorrection(claim: Claim): boolean {
100	  return cents(claim.amount) < 0;
101	}
102	
103	/** Whether a claim counts toward what is claimed and due: only OPEN, PENDING and SETTLED ones do. */
104	export function counts(claim: Claim): boolean {
105	  return isOpen(claim) || claim.status === 'SETTLED';
106	}
