113	/** An amount in cents, from the two-decimal string the server sends. */
114	export function cents(amount: string): number {
115	  return Math.round(Number(amount) * 100);
116	}
117	
118	/** What a late charge works from: the sheet's late percent (two decimals) in force on a date, its today and
119	 *  a claim's grace days (see graceOn in the settings); and what a claim's figures round by: the sheet's
120	 *  policy date (blank for its today). */
121	export interface Late {
122	  pct: (date: string) => string;
123	  today: string | null;
124	  policyDate: string;
125	  grace: (claim: Claim) => number;
126	}
127	
128	/** Whether a claim's live figures round half up: it rounds by a date before the sheet's policy date
129	 *  (its today when the policy date is blank); otherwise they round half to even. */
130	function roundsHalfUp(claim: Claim, late: Late): boolean {
131	  const policy = late.policyDate !== '' ? late.policyDate : late.today;
132	  return policy !== null && claim.roundsBy < policy;
133	}
134	
135	/** A claim's figure in cents: the figure a statement bound it to, unless it is PENDING (no statement
136	 *  binds it then); otherwise its amount times the rate in force on its date among its grade's rates;
137	 *  null when it has no figure. The floor is not applied here (see claimDueCents). */
138	function figureCents(claim: Claim, rates: Rate[], halfUp: boolean): number | null {
139	  if (claim.stated && claim.status !== 'PENDING') return claim.statedDue === null ? null : cents(claim.statedDue);
140	  const rate = rateOn(rates, claim.date);
141	  if (rate === null) return null;
142	  return dueCents(cents(claim.amount), rate, halfUp);
143	}
144	
145	/** A claim's due in cents: the due fixed when it was settled; otherwise the greater of the sheet's floor
146	 *  in force on its date (none for a correction) and its figure plus its late charge: for every full 30
147	 *  days an OPEN or PENDING claim is overdue, the late percent in force on that boundary (its due-by plus
148	 *  30, 60, 90 ... days) of the figure plus the charges of the boundaries before it (compounding), rounded
149	 *  like a due, the charges added up (a statement never binds
150	 *  the charge; settling freezes the due; a correction has none); null when it has no figure. */
151	export function claimDueCents(claim: Claim, rates: Rate[], floor: (date: string) => number, late: Late): number | null {
152	  if (claim.settledDue !== null) return cents(claim.settledDue);
153	  const halfUp = roundsHalfUp(claim, late);
154	  const figure = figureCents(claim, rates, halfUp);
155	  if (figure === null) return null;
156	  if (isCorrection(claim)) return figure;
157	  const grace = late.grace(claim);
158	  const periods = Math.floor(daysOverdue(claim, late.today, grace) / 30);
159	  let charge = 0;
160	  for (let boundary = 1; boundary <= periods; boundary++) {
161	    const pct = late.pct(plusDays(claim.dueBy, grace + 30 * boundary));
162	    if (cents(pct) !== 0) charge += dueCents(figure + charge, pct, halfUp);
163	  }
164	  return Math.max(figure + charge, floor(claim.date));
165	}
166	
167	/** A date (yyyy-mm-dd) some days on. */
168	export function plusDays(date: string, days: number): string {
169	  return new Date(Date.parse(date) + days * 86_400_000).toISOString().slice(0, 10);
170	}
171	
172	/** How many days an OPEN or PENDING claim is past its due-by plus its grace days on the sheet's today; 0
173	 *  when it is not overdue. */
174	function daysOverdue(claim: Claim, today: string | null, grace: number): number {
175	  if (!overdue(claim, today, grace) || today === null) return 0;
176	  return Math.round((Date.parse(today) - Date.parse(plusDays(claim.dueBy, grace))) / 86_400_000);
177	}
178	
179	/** Whether a claim is overdue: it is OPEN or PENDING, not deferred, and its due-by plus its grace days
180	 *  (those of its person's grade in force on its date; none by default) is before the sheet's today. */
181	export function overdue(claim: Claim, today: string | null, grace = 0): boolean {
182	  return isOpen(claim) && today !== null && plusDays(claim.dueBy, grace) < today && !deferred(claim, today);
183	}
