541	  constructor() {
542	    // A claim the user still locks (an editor left open before the sheet was re-loaded) opens in
543	    // the editor again, once the person's claims first show.
544	    effect(() => {
545	      const claims = this.claims();
546	      if (this.restored || claims.length === 0) return;
547	      this.restored = true;
548	      const user = untracked(this.session.user);
549	      const mine = claims.find((c) => c.status === 'DRAFT' && user !== null && c.lockedBy === user);
550	      if (mine) untracked(() => this.fill(mine));
551	    });
552	    // A change of the sheet's today releases every lock, so it closes the editor too.
553	    let today: string | null | undefined;
554	    effect(() => {
555	      const now = this.session.today();
556	      if (today !== undefined && now !== today) untracked(() => this.reset());
557	      today = now;
558	    });
559	  }
