606	  /** Open the editor on a DRAFT claim, locking it for other users until it is saved or cancelled.
607	   *  Any other claim cannot be edited (an OPEN one is voided and added again), nor can one in a
608	   *  closed period, one another user's editor locks, or any claim by a viewer: each is refused on
609	   *  the row and takes no lock. */
610	  protected async edit(claim: Claim): Promise<void> {
611	    this.rowError.set(null);
612	    const refused = this.editRefusal(claim);
613	    if (refused !== null) {
614	      this.rowError.set({ id: claim.id, message: refused });
615	      return;
616	    }
617	    const sheet = this.session.sheetId();
618	    if (!sheet) return;
619	    const previous = this.editingId();
620	    this.fill(claim);
621	    const base = `/api/sheets/${encodeURIComponent(sheet)}/people/${this.personId()}/claims`;
622	    try {
623	      const locked = await firstValueFrom(this.http.post<Claim>(`${base}/${claim.id}/lock`, null));
624	      if (this.session.sheetId() !== sheet) return;
625	      this.saved.emit(locked);
626	      if (previous !== null && previous !== claim.id) void this.unlock(sheet, previous);
627	    } catch (e) {
628	      if (this.session.sheetId() !== sheet) return;
629	      if (this.editingId() === claim.id) {
630	        // The editor goes back to the claim it had open before, whose lock the user still holds.
631	        const back = previous !== claim.id ? this.claims().find((c) => c.id === previous) : undefined;
632	        if (back) this.fill(back);
633	        else this.reset();
634	      }
635	      const forbidden = e instanceof HttpErrorResponse && e.status === 403;
636	      this.rowError.set({
637	        id: claim.id,
638	        message: forbidden
639	          ? 'The claim cannot be edited: your role may not change this sheet.'
640	          : 'The claim cannot be edited: only a draft outside a closed period can, and not while another user is editing it.',
641	      });
642	    }
643	  }
