645	  /** Why the edit button is refused on a claim, as far as the screen can tell; null when it is not. */
646	  private editRefusal(claim: Claim): string | null {
647	    const user = this.session.user();
648	    if (claim.status !== 'DRAFT') return `A ${claim.status} claim cannot be edited; only a draft can.`;
649	    if (this.viewer()) {
650	      return 'The claim cannot be edited: a viewer can change nothing on this sheet.';
651	    }
652	    if (periodOf(this.periods.periods(), claim.dueBy)?.closed) {
653	      return `The claim cannot be edited: it is due by a day in the closed period ${periodOf(this.periods.periods(), claim.dueBy)?.name}.`;
654	    }
655	    if (claim.lockedBy !== null && claim.lockedBy !== user) {
656	      return `The claim cannot be edited: ${claim.lockedBy} is editing it.`;
657	    }
658	    return null;
659	  }
