985	      this.error.set(
986	        forbidden
987	          ? 'The claim could not be added: your role may not change this sheet.'
988	          : `The claim could not be added from the template ${template}.`,
989	      );
990	    } finally {
991	      this.busy.set(false);
992	    }
993	  }
994	
995	  /** Open, settle, approve, reject (with the reason typed on its row), void or re-settle a claim; a clerk
996	   *  settling a due above the clerk limit leaves it PENDING. A change its status does not allow, the
997	   *  user who opened it settling or approving it, anyone but a steward approving or rejecting it, or
998	   *  a reject with no reason, is refused on the row. */
999	  protected async act(claim: Claim, action: ClaimAction): Promise<void> {
1000	    this.rowError.set(null);
1001	    const sheet = this.session.sheetId();
1002	    if (!sheet) return;
1003	    const reason = (this.rejectReasons()[claim.id] ?? '').trim();
1004	    if (action === 'reject' && reason === '') {
1005	      this.rowError.set({ id: claim.id, message: 'Type the reason the claim is rejected.' });
1006	      return;
