1009	    if (action === 'void' && voidReason === '' && this.voidReasons.reasons().length > 0) {
1010	      this.rowError.set({ id: claim.id, message: 'Choose the reason the claim is voided.' });
1011	      return;
1012	    }
1013	    const url =
1014	      `/api/sheets/${encodeURIComponent(sheet)}/people/${this.personId()}/claims/${claim.id}/${action}`;
1015	    try {
1016	      const saved = await firstValueFrom(this.http.post<Claim>(
1017	          url,
1018	          action === 'reject' ? { reason } : action === 'void' ? { reason: voidReason || null } : null,
1019	        ),
1020	      );
1021	      if (this.session.sheetId() !== sheet) return;
1022	      if (action === 'reject') this.setRejectReason(claim.id, '');
1023	      this.saved.emit(saved);
1024	    } catch (e) {
1025	      const forbidden = e instanceof HttpErrorResponse && e.status === 403;
1026	      this.rowError.set({
1027	        id: claim.id,
1028	        message:
1029	          forbidden && action === 'settle'
1030	            ? 'The claim could not be settled: whoever opened it cannot settle it, and your role must be allowed to settle.'
1031	            : !forbidden && (action === 'settle' || action === 'approve')
1032	              ? `The claim could not be ${PAST[action]}: one due above the proof threshold needs a proof first, and its status must allow it.`
1033	            : !forbidden && action === 'delete'
