1041	              : !forbidden && action === 'void' && this.voidReasons.reasons().length > 0
1042	                ? 'The claim could not be voided: choose a reason from the list, and its status must allow it.'
1043	              : !forbidden && action === 'void' && claim.status === 'SETTLED'
1044	                ? 'The claim could not be voided: only a steward voids a settled claim, within 7 days of its settlement and outside a closed period.'
1045	              : forbidden
1046	                ? action === 'open' || action === 'void' || action === 'delete' || action === 'restore'
