/** Take a statement for the person, now or as of a day. */
@PostMapping
public StatementTaken take(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
        @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
        @RequestBody(required = false) StatementRequest request) {
    String sheet = sheetId.trim();
    String by = SignedInUser.decode(user);
    LocalDate asOf = request != null ? request.asOf() : null;
    List<ClaimView> claims = rollups.track(sheet, by, () -> service.take(sheet, by, personId, asOf)).stream()
            .map(claim -> ClaimView.of(claim, claimService.roundsBy(sheet, claim),
                    claimService.logOf(claim.getId()), claimService.commentsOf(claim.getId()))).toList();
    return new StatementTaken(service.summary(sheet, personId), claims);
}

/** Cancel the person's last statement: their statements as their row then shows them, and their
 *  claims, newest first, now live again. */
@DeleteMapping
public StatementTaken cancel(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
        @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
    String sheet = sheetId.trim();
    String by = SignedInUser.decode(user);
    List<ClaimView> claims = rollups.track(sheet, by, () -> service.cancel(sheet, by, personId)).stream()
            .map(claim -> ClaimView.of(claim, claimService.roundsBy(sheet, claim),
                    claimService.logOf(claim.getId()), claimService.commentsOf(claim.getId()))).toList();
    return new StatementTaken(service.summary(sheet, personId), claims);
}

@ExceptionHandler(StatementRefusedException.class)
@ResponseStatus(HttpStatus.CONFLICT)
public void refusedAsOf() {
}
@PostMapping("/generate")
public GenerateView generate(@PathVariable @NotBlank @Size(max = 200) String sheetId,
        @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
    String sheet = sheetId.trim();
    String by = SignedInUser.decode(user);
    List<Claim> made = rollups.track(sheet, by, () -> service.generate(sheet, by));
    return new GenerateView(made.stream()
            .map(c -> ClaimView.of(c, claims.roundsBy(sheet, c), claims.logOf(c.getId()), List.of()))
            .toList(), views(sheet, null));
}

public PasteView paste(@PathVariable @NotBlank @Size(max = 200) String sheetId,
        @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated PasteRequest request) {
    String sheet = sheetId.trim();
    String by = SignedInUser.decode(user);
    return new PasteView(service.paste(sheet, by, request.text()).stream()
            .map(c -> ClaimView.of(c, c.getDate(), claims.logOf(c.getId()), List.of())) // never a correction
            .toList());
}

    return new QuickAddView(PersonView.of(added.person(), grades.of(personId), sheets.today(sheet),
            statements.summary(sheet, personId), people.holds(personId), people.patronIds(personId),
            people.watches(personId, by), people.aliases(personId), people.clashing(added.person()),
            people.retirements(personId)),
            ClaimView.of(added.claim(), added.claim().getDate(),
                    claims.logOf(added.claim().getId()), List.of())); // never a correction: rounds by its own date
}

/** A claim dated in a closed period or after its person retired, or a name taken at the same moment, is refused. */

